result.output:
120	            .publish_to
121	            .iter()
122	            .all(|target| matches!(target, callisto_model::PublishTarget::None))
123	        {
124	            ReleaseSelectionInvalidReason::NoDispatchableTarget
125	        } else {
126	            continue;
127	        };
128	        return Err(GraphError::ReleaseSelectionInvalid {
129	            package: (*selection).clone(),
130	            reason,
131	        });
132	    }
133	
134	    let entries = expand_selection(workspace, complete.entries, &selected);
135	    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
136	}
