174	/// Derives the roster of every publishable package whose current version has
175	/// no tag in the canonical [`crate::TagIndex`], each with
176	/// [`ReleaseInclusionReason::UnreleasedVersion`].
177	///
178	/// A non-empty `selections` restricts the roster to exactly those identities,
179	/// each of which must be unreleased and publishable. `None` means nothing is
180	/// unreleased.
181	pub fn derive_unreleased_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
182	    workspace: &Workspace<'_, R, D>,
183	    selections: &[ReleasePackageId],
184	) -> Result<Option<ReleaseDecisionV1>, GraphError> {
185	    let versions = workspace.base_versions()?;
186	    let tags = workspace.tags()?;
187	    let mut entries = Vec::new();
188	    for package in workspace.graph.packages() {
189	        if !has_dispatchable_target(package) {
190	            continue;
191	        }
192	        let version = versions.get(&package.id).ok_or_else(|| GraphError::ReleaseInvariant {
193	            detail: format!("package `{}` has no base version", package.id.display_name()),
194	        })?;
195	        if version_is_tagged(tags, &package.id, version) {
196	            continue;
197	        }
198	        for id in release_package_ids(&workspace.identity, package)? {
199	            entries.push(ReleaseDecisionEntry {
200	                package: id,
201	                target_version: version.clone(),
202	                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
203	            });
204	        }
205	    }
206	
207	    let mut seen = std::collections::BTreeSet::new();
208	    for selection in selections {
209	        if !seen.insert(selection) {
210	            return Err(GraphError::ReleaseSelectionInvalid {
211	                package: selection.clone(),
212	                reason: ReleaseSelectionInvalidReason::Duplicate,
213	            });
214	        }
215	        let Some(package) = workspace_package(workspace, selection) else {
216	            return Err(GraphError::UnknownPackage {
217	                id: callisto_model::PackageId::Prefixed {
218	                    ecosystem: selection.ecosystem(),
219	                    name: selection.name().to_string(),
220	                },
221	            });
222	        };
223	        if !has_dispatchable_target(package) {
224	            return Err(GraphError::ReleaseSelectionInvalid {
225	                package: selection.clone(),
226	                reason: ReleaseSelectionInvalidReason::NoDispatchableTarget,
227	            });
228	        }
229	        if !entries.iter().any(|entry| &entry.package == selection) {
230	            return Err(GraphError::ReleaseSelectionInvalid {
231	                package: selection.clone(),
232	                reason: ReleaseSelectionInvalidReason::NotARelease,
233	            });
234	        }
235	    }
236	    if !selections.is_empty() {
237	        entries = expand_selection(workspace, entries, &seen);
238	    }
239	    if entries.is_empty() {
240	        return Ok(None);
241	    }
242	    ReleaseDecisionV1::new(entries).map(Some).map_err(GraphError::from)
243	}
