274	/// The fixed and linked groups a release package belongs to, per config.
275	fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
276	    workspace: &Workspace<'_, R, D>,
277	    id: &ReleasePackageId,
278	) -> Vec<(&'static str, callisto_model::GroupName)> {
279	    let Some(package) = workspace_package(workspace, id) else {
280	        return Vec::new();
281	    };
282	    let groups = &workspace.config.groups;
283	    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
284	    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
285	    // `member` keys are already canonical (`GroupTable::resolve` resolved
286	    // them through `IdentityIndex::resolve`), so exact equality is correct
287	    // here -- `PackageId::matches` would treat a Bare member key as an
288	    // ecosystem wildcard and could match a same-named package elsewhere.
289	    fixed
290	        .chain(linked)
291	        .filter(|(_, member, _)| **member == package.id)
292	        .map(|(kind, _, group)| (kind, group.clone()))
293	        .collect()
294	}
