296	/// Verifies the release roster a merged release commit claims, against a
297	/// release-decision file committed alongside it at `decision_path`.
298	///
299	/// This is intentionally *not* a second computation of changeset, fixed-group,
300	/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
301	/// (via [`derive_release_decision`]) already computed that once, correctly,
302	/// when the release PR was generated -- and `callisto version --emit-decision`
303	/// commits its exact output alongside the manifest and changelog edits.
304	/// Re-deriving that policy a second time here, from raw git diffs, is exactly
305	/// the kind of duplicated logic that drifts: an earlier version of this
306	/// function did just that, understood only a direct changeset match, and
307	/// rejected every real release in this repository once a fixed-group cascade
308	/// (a case its reimplementation never learned) touched an unnamed sibling.
309	///
310	/// Instead, this function reads the committed decision back and confirms the
311	/// commit's actual diff matches it exactly -- no more, no less.
312	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
313	/// entries don't match its content digest, so a hand-edited or corrupted
314	/// decision file fails before this function's own diff cross-check runs.
315	///
316	/// The caller must check out the exact merge commit in detached HEAD state
317	/// before creating an intent. GitHub-specific PR/approval provenance belongs
318	/// in the workflow boundary; this graph function verifies the local,
319	/// provider-neutral commit delta only.
320	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
321	    workspace: &Workspace<'_, R, D>,
322	    release_commit: &CommitSha,
323	    decision_path: &std::path::Path,
324	) -> Result<ReleaseDecisionV1, GraphError> {
325	    let head_args = ["rev-parse", "HEAD"];
326	    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
327	    let head =
328	        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
329	    if &head != release_commit {
330	        return Err(GraphError::ReleaseCommitVerificationFailed {
331	            commit: release_commit.clone(),
332	            reason: CommitVerificationFailure::HeadMismatch,
333	        });
334	    }
335	
336	    let parent_ref = format!("{}^", release_commit.as_str());
337	    let parent_args = ["rev-parse", parent_ref.as_str()];
338	    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
339	    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
340	
341	    let diff_tree_args = [
342	        "diff-tree",
343	        "--no-commit-id",
344	        "--name-status",
345	        "-r",
346	        "--no-renames",
347	        parent.as_str(),
348	        release_commit.as_str(),
349	    ];
350	    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
351	    let changed = parse_name_status(&changed, &diff_tree_args)?;
352	
353	    // The decision must be freshly authored as part of *this* commit, not a
354	    // stale leftover an earlier release already committed and this one never
355	    // touched -- otherwise a commit that changes nothing real could still
356	    // carry forward a prior, unrelated decision's authority.
357	    let decision_path_str = normalized_git_path(decision_path)?;
358	    let decision_freshly_written = changed
359	        .iter()
360	        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
361	    if !decision_freshly_written {
362	        return Err(GraphError::ReleaseCommitVerificationFailed {
363	            commit: release_commit.clone(),
364	            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
365	        });
366	    }
367	
368	    // A cheap, independent sanity check that this commit is a real version
369	    // application and not just a hand-crafted decision file: some real
370	    // changeset was actually consumed. The decision's own entries, not this
371	    // changeset's content, remain the sole authority verified below.
372	    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
373	    let consumed_a_changeset = changed
374	        .iter()
375	        .any(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir));
376	    if !consumed_a_changeset {
377	        return Err(GraphError::ReleaseCommitVerificationFailed {
378	            commit: release_commit.clone(),
379	            reason: CommitVerificationFailure::NoChangesetConsumed,
380	        });
381	    }
382	
383	    let decision_source = git_file(
384	        workspace.runner,
385	        &workspace.root,
386	        release_commit.as_str(),
387	        &decision_path_str,
388	    )?;
389	    let decision: ReleaseDecisionV1 =
390	        serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
391	            path: decision_path.to_path_buf(),
392	            message: error.to_string(),
393	        })?;
394	    let claimed = decision
395	        .entries
396	        .iter()
397	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
398	        .collect::<std::collections::BTreeMap<_, _>>();
399	
400	    let changed_paths = changed
401	        .iter()
402	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
403	        .collect::<std::collections::BTreeSet<_>>();
404	
405	    // Every canonical manifest path this workspace currently declares, in
406	    // the exact order `workspace.graph.packages()` and
407	    // `Package::canonical_manifests()` yield -- both are backed by ordered
408	    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
409	    // the second traversal below visits the same (package, manifest) pairs
410	    // in the same order. That lets it zip the batched `before`/`after`
411	    // results back on by position instead of re-keying by path, which would
412	    // misbehave if two packages ever declared an identical manifest path.
413	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
414	        .graph
415	        .packages()
416	        .flat_map(Package::canonical_manifests)
417	        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
418	        .collect::<Result<_, GraphError>>()?;
419	    let mut query_paths: Vec<&str> = manifest_queries.iter().map(|(path, _)| path.as_str()).collect();
420	    if manifest_queries
421	        .iter()
422	        .any(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
423	        && !query_paths.contains(&"Cargo.toml")
424	    {
425	        query_paths.push("Cargo.toml");
426	    }
427	
428	    // Exactly two `git cat-file --batch` subprocess invocations total (one
429	    // per commit), regardless of how many canonical manifests the
430	    // workspace has -- replaces what was previously 2*N separate `git
431	    // show` spawns (one `manifest_version_at` call per manifest per
432	    // commit).
433	    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, &parent, &query_paths)?;
434	    let after_blobs =
435	        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
436	    let before_versions = resolve_batch_versions(before_blobs, &query_paths, &manifest_queries)?;
437	    let after_versions = resolve_batch_versions(after_blobs, &query_paths, &manifest_queries)?;
438	
439	    let mut observed = std::collections::BTreeSet::new();
440	    let mut manifest_index = 0usize;
441	    for package in workspace.graph.packages() {
442	        let package_ids = release_package_ids(&workspace.identity, package)?;
443	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
444	        if package_is_claimed {
445	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
446	                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
447	            })?;
448	            let changelog = normalized_git_path(changelog)?;
449	            if !changed_paths.contains(changelog.as_str()) {

60	            package: package.id.display_name(),
61	        }));
62	    }
63	    let matrix = crate::commands::matrix(workspace, &crate::commands::MatrixOptions::default())?;
64	    Ok(matrix
65	        .platform_targets
66	        .keys()
67	        .next()
68	        .map(|package| CiReleaseRoute::PlatformPackage {
69	            package: package.clone(),
70	        }))
71	}
