19	/// Executes eligible operations one at a time.
20	///
21	/// The run `envelope` was created and validated before this call. Each
22	/// operation is observed once before any effect: an exact observation is
23	/// adopted as already satisfied, an absent one is published and confirmed,
24	/// and anything else stops the run before an effect is issued.
25	pub fn execute_release<P: ReleaseProviderSet + ?Sized>(
26	    capability: &P,
27	    permit: &ApplyPermit,
28	    envelope: &ReleaseRunEnvelopeV1,
29	    artifacts: Option<&VerifiedArtifactManifest<'_>>,
30	) -> Result<ReleaseExecutionStateV1, GraphError> {
31	    let intent = capability.intent();
32	    require_verified_artifact_manifest(intent, artifacts)?;
33	    envelope
34	        .validate_for_intent(intent)
35	        .map_err(|source| GraphError::ReleaseRunEnvelope { source })?;
36	    let mut state = ReleaseExecutionStateV1::new(intent, envelope.clone())
37	        .map_err(|source| GraphError::ReleaseExecutionState { source })?;
38	    while let Some(operation) = eligible_operations(intent, &state).first().cloned() {
39	        capability.recheck_trust()?;
40	        let event = match capability.preflight(&operation, artifacts)? {
41	            ReleasePreflight::AlreadySatisfied { evidence } => {
42	                warn_if_registry_version_adopted(&operation);
43	                OperationEvent::ObservedExactBeforeEffect { evidence }
44	            }
45	            ReleasePreflight::Proceed { proof } => {
46	                let attempt = OperationEvent::Attempt { proof };
47	                apply(&mut state, &operation, &attempt)?;
48	                // The proof stays borrowed from the recorded attempt: only an
49	                // attempt may authorize the effect that follows it.
50	                let OperationEvent::Attempt { proof } = &attempt else {
51	                    return Err(GraphError::ReleaseInvariant {
52	                        detail: "the attempt event just built is not an Attempt".to_owned(),
53	                    });
54	                };
55	                OperationEvent::Confirmed {
56	                    evidence: capability.publish(permit, proof, &operation, artifacts)?,
57	                }
58	            }
59	        };
60	        apply(&mut state, &operation, &event)?;
61	    }
62	    require_terminal_success(intent, &state)?;
63	    Ok(state)
64	}
