149	/// The pending operations whose every transitive prerequisite is exactly
150	/// `Published` or `AlreadySatisfied`, in the intent's canonical order.
151	pub(crate) fn eligible_operations(
152	    intent: &ReleaseIntentV1,
153	    state: &ReleaseExecutionStateV1,
154	) -> Vec<ReleaseOperationId> {
155	    let prerequisites: BTreeMap<_, _> = intent
156	        .operations
157	        .iter()
158	        .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec()))
159	        .collect();
160	    let mut satisfied = BTreeMap::new();
161	    intent
162	        .operations
163	        .iter()
164	        .filter(|operation| state.operation_state(operation.id()) == Some(OperationState::Pending))
165	        .filter(|operation| {
166	            prerequisites_satisfied_transitively(
167	                operation.id(),
168	                &prerequisites,
169	                state,
170	                &mut BTreeSet::new(),
171	                &mut satisfied,
172	            )
173	        })
174	        .map(|operation| operation.id().clone())
175	        .collect()
176	}
